pub fn lis(xs: List[Int]) -> List[Int] {
  let n = xs.len()
  // best[i] = length of the longest increasing subsequence that starts at index i
  var best: List[Int] = range(0, n).map(fn(_i) => 0)
  for i in range(0, n).reverse() {
    var bi = 1
    for j in range(i + 1, n) {
      if xs.get_or(j, 0) > xs.get_or(i, 0) and best.get_or(j, 0) + 1 > bi {
        bi = best.get_or(j, 0) + 1
      }
    }
    best = best.set(i, bi)
  }
  let longest = best.max().unwrap_or(0)
  var out: List[Int] = []
  var cur = -1
  var prev_val = 0
  var has_prev = false
  var need = longest
  while need > 0 {
    var pick = -1
    var pick_val = 0
    for j in range(cur + 1, n) {
      let v = xs.get_or(j, 0)
      let fits = (not has_prev) or v > prev_val
      if best.get_or(j, 0) == need and fits and (pick < 0 or v < pick_val) {
        pick = j
        pick_val = v
      }
    }
    out = out.push(pick_val)
    cur = pick
    prev_val = pick_val
    has_prev = true
    need = need - 1
  }
  return out
}
